def lca(u, v, depths, parents):
    if depths[u] < depths[v]:
        u, v = v, u
    diff = depths[u] - depths[v]
    for i in range(17):
        if (diff >> i) & 1:
            u = parents[u][i]
    if u == v:
        return u
    for i in range(16, -1, -1):
        if parents[u][i] != parents[v][i]:
            u = parents[u][i]
            v = parents[v][i]
    return parents[u][0]

def query(u, v, values, depths, parents):
    anc = lca(u, v, depths, parents)
    max_xor = 0
    while u != anc:
        max_xor = max(max_xor, values[u] ^ values[v])
        u = parents[u][0]
    while v != anc:
        max_xor = max(max_xor, values[u] ^values[v])
        v = parents[v][0]
    max_xor = max(max_xor, values[u] ^ values[v])
    return max_xor

